messages.content:
Tool response:
Tool: bulk_update_min_stay
Description: Updates the minimum stay requirement for specified RV sites during a given date range.
Parameters:
    {
      "type": "object",
      "properties": {
        "campsite_ids": {
          "items": {
            "type": "integer"
          },
          "type": "array",
          "title": "Campsite Ids",
          "description": "List of RV site IDs to update"
        },
        "start_date": {
          "type": "string",
          "format": "date",
          "title": "Start Date",
          "description": "Start date of the period to update (inclusive)"
        },
        "end_date": {
          "type": "string",
          "format": "date",
          "title": "End Date",
          "description": "End date of the period to update (inclusive)"
        },
        "min_nights": {
          "type": "integer",
          "title": "Min Nights",
          "description": "New minimum stay requirement in nights"
        }
      },
      "required": [
        "campsite_ids",
        "start_date",
        "end_date",
        "min_nights"
      ]
    }
